import {executionFields,outcomeSummary,presentResult} from './runtime/interaction/result-presentation.js';
/** Persistent lazy sections inside the existing Agent Task panel. All response content uses textContent. */
export function createExecutionResultsView(host,onModeChange=()=>{}){
 const section=document.createElement('section');section.className='execution-results';section.hidden=true;
 section.innerHTML=`<details data-result-section><summary>Execution result</summary><h4 tabindex="-1" data-result-title>Current Execution result</h4><p data-result-context></p><div class="inspect-actions"><button type="button" data-result-current>Return to current Execution</button><button type="button" data-result-refresh>Refresh result</button></div><p data-result-feedback role="status" aria-live="polite"></p><dl data-result-metadata></dl><p data-result-outcome></p><p data-result-label></p><pre data-result-content tabindex="0" aria-label="Execution output"></pre></details>
 <details data-history-section><summary>Execution history</summary><p>Agent-scoped history snapshot, newest first. One page of up to 10 records; results load only when selected. Refresh to see new executions.</p><button type="button" data-history-refresh>Refresh history from first page</button><p data-history-feedback role="status" aria-live="polite"></p><ul data-history-list class="runtime-reference-list"></ul><div class="inspect-actions"><button type="button" data-history-previous>Previous page</button><span data-history-page></span><button type="button" data-history-next>Next page</button></div></details>`;
 host.append(section);const q=s=>section.querySelector(s);let owner=null,off=null,disposed=false,lastItems=null,historyMode=false;const rowButtons=new Map();
 const text=(selector,value)=>{const element=q(selector);if(element.textContent!==value)element.textContent=value;};
 q('[data-result-section]').addEventListener('toggle',()=>owner?.openResult(q('[data-result-section]').open));
 q('[data-history-section]').addEventListener('toggle',()=>owner?.openHistory(q('[data-history-section]').open));
 q('[data-result-current]').onclick=()=>{owner?.returnToCurrent();q('[data-result-title]').focus({preventScroll:true});};q('[data-result-refresh]').onclick=()=>void owner?.refreshResult();
 q('[data-history-refresh]').onclick=()=>void owner?.refreshHistory();q('[data-history-next]').onclick=()=>void owner?.nextPage();q('[data-history-previous]').onclick=()=>void owner?.previousPage();
 function render(){if(disposed)return;const s=owner?.getSnapshot();section.hidden=!s?.agentId;
  const nextMode=s?.mode==='HISTORY';if(historyMode!==nextMode){historyMode=nextMode;onModeChange(historyMode);}
  if(!s?.agentId){text('[data-result-context]','');text('[data-result-feedback]','');text('[data-result-outcome]','');text('[data-result-label]','');text('[data-result-content]','');text('[data-history-feedback]','');text('[data-history-page]','');q('[data-history-list]').replaceChildren();q('[data-result-metadata]').replaceChildren();delete q('[data-result-metadata]').dataset.fields;lastItems=null;rowButtons.clear();return;}
  text('[data-result-title]',s.mode==='HISTORY'?'Selected historical Execution':'Current control target / latest reference');
  text('[data-result-context]',s.mode==='HISTORY'?'Historical selection is read-only and does not change NPC activity. Return to current Execution before using lifecycle controls.':'This is the T05 control target or latest authorized reference. It may be terminal; Agent-wide activity above remains the live observation source.');
  text('[data-result-feedback]',s.resultLoading?'Loading authorized result…':s.resultError||(!s.canRead?'Activity/access is stale or unavailable; displayed content is last known.':s.detailStale?'Last-known detail; refresh before treating this observation as fresh.':!s.selected?'No Execution has been recorded for this control target.':''));
  q('[data-result-section]').setAttribute('aria-busy',String(s.resultLoading));q('[data-result-current]').hidden=s.mode!=='HISTORY';q('[data-result-refresh]').disabled=!s.canRead||s.resultLoading||!s.selected;
  const fields=executionFields(s.detail),signature=JSON.stringify(fields);if(q('[data-result-metadata]').dataset.fields!==signature){q('[data-result-metadata]').replaceChildren();for(const [label,value]of fields){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;q('[data-result-metadata]').append(dt,dd);}q('[data-result-metadata]').dataset.fields=signature;}
  text('[data-result-outcome]',s.detail?outcomeSummary(s.detail):s.resultLoading?'Execution detail loading.':s.selected?'Execution details unavailable.':outcomeSummary(null));const result=presentResult(s.result);text('[data-result-label]',result.label);text('[data-result-content]',result.text);q('[data-result-content]').hidden=!result.text;
  text('[data-history-feedback]',s.historyLoading?'Loading authorized history page…':s.historyError||(!s.canRead?'History is a last-known snapshot; activity/access is stale.':s.historyDirty?'New execution data is available. Refresh the first page; historical selection remains unchanged.':s.historyLoaded&&!s.items.length?(s.page===1?'No Execution history is available.':'No executions on this page.'):'History is a bounded snapshot; use Refresh to observe changes.'));
  q('[data-history-section]').setAttribute('aria-busy',String(s.historyLoading));q('[data-history-refresh]').disabled=!s.canRead||s.historyLoading;
  q('[data-history-previous]').disabled=!s.canPrevious;q('[data-history-next]').disabled=!s.canNext;text('[data-history-page]',`Page ${s.page}${s.pageLimitReached?' · 20-page limit; refresh first page':''}`);
  if(lastItems!==s.items){const focused=[...rowButtons].find(([,button])=>button===document.activeElement)?.[0];lastItems=s.items;rowButtons.clear();q('[data-history-list]').replaceChildren();for(const item of s.items){const li=document.createElement('li'),button=document.createElement('button');button.type='button';button.textContent=`${item.status} · Execution ${item.id} · Task ${item.taskId} · Created ${item.createdAt}`;
   button.onclick=()=>{q('[data-result-section]').open=true;owner.selectHistory(item.id);q('[data-result-title]').focus({preventScroll:true});};rowButtons.set(item.id,button);li.append(button);q('[data-history-list]').append(li);}if(focused)(rowButtons.get(focused)??q('[data-history-section] summary')).focus({preventScroll:true});}
  for(const [id,button]of rowButtons)button.setAttribute('aria-pressed',String(s.mode==='HISTORY'&&s.selected?.executionId===id));
 }
 return Object.freeze({attach(readOwner){off?.();owner=readOwner;off=owner.subscribe(render);owner.openResult(q('[data-result-section]').open);owner.openHistory(q('[data-history-section]').open);render();},
  select(binding,execution){owner?.select(binding,execution);render();},clear(){owner?.clear();render();},dispose(){disposed=true;off?.();section.remove();}});
}
